-- the pair recorded in a config.lua text, or nil (the same reading as server/tools/client_pair.py parse)
function M.parsePair(text)
	if type(text) ~= "string" then
		return nil
	end
	local v = text:match("^%s*chaosClientPair%s*=%s*(%d+)%s*%-?%-?[^\n]*$") or text:match("\n%s*chaosClientPair%s*=%s*(%d+)%s*%-?%-?[^\n]*")
	return v and tonumber(v) or nil
end

function M.recordedPair(path)
	local f = io.open(path or "config.lua", "r")
	if not f then
		return nil
	end
	local text = f:read("*a")
	f:close()
	return M.parsePair(text)
end

-- the gate, read once at load; tests set it by hand
M.on = (M.recordedPair() or 0) >= M.PAIR

-- the names join ChaosVfx (chaos_vfx.lua), so the cosmetics window and the store play them like any effect; at load
-- while the gate is on, by hand (a test) after it is set
function M.merge()
	if not ChaosVfx then
		pcall(dofile, "data/lib/chaos_vfx.lua")
	end
	ChaosVfx = ChaosVfx or {}
	for name, e in pairs(M.effects) do
		ChaosVfx[name] = {id = e.id, dx = e.dx, dy = e.dy, ms = e.ms}
	end
end

if M.on then
	M.merge()
end

